public class CommentsConfigurationTest {

    private static final String PATH = "/path/to/comment";
    private static final String NEWLINE = "\n";

    @Test
    public void newCommentsConfiguration_isCreatedWithEmptyMap() {
        // Given:
        CommentsConfiguration commentsConfig = new CommentsConfiguration();

        // When:
        Map<String, List<String>> comments = commentsConfig.getAllComments();

        // Then:
        assertTrue(comments.isEmpty());
    }

    @Test
    public void newCommentsConfiguration_isCreatedWithExistingMap() {
        // Given:
        Map<String, List<String>> existingComments = new HashMap<>();
        existingComments.put(PATH, Arrays.asList("existing", "comment"));
        CommentsConfiguration commentsConfig = new CommentsConfiguration(existingComments);

        // When:
        Map<String, List<String>> comments = commentsConfig.getAllComments();

        // Then:
        assertEquals(existingComments, comments);
    }

    @Test
    public void setComment_overwritesExistingCommentForPath() {
        // Given:
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration commentsConfig = new CommentsConfiguration(comments);
        String[] commentLines = {"new", "comment"};
        commentsConfig.setComment(PATH, NEWLINE, commentLines);

        // When:
        Map<String, List<String>> updatedComments = commentsConfig.getAllComments();

        // Then:
        assertEquals(Arrays.asList(commentLines), updatedComments.get(PATH));
    }

    @Test
    public void setComment_setsSingleNewlineAsEmptyLineWithoutCommentMarker() {
        // Given:
        String path = PATH;
        CommentsConfiguration commentsConfig = new CommentsConfiguration();
        String[] commentLines = {NEWLINE};
        commentsConfig.setComment(path, NEWLINE);

        // When:
        Map<String, List<String>> updatedComments = commentsConfig.getAllComments();

        // Then:
        assertEquals(0, updatedComments.get(path).size());
    }

    @Test
    public void setComment_setsMultipleNewlinesAsEmptyLinesWithoutCommentMarkers() {
        // Given:
        String path = PATH;
        CommentsConfiguration commentsConfig = new CommentsConfiguration();
        String[] commentLines = {NEWLINE, NEWLINE, "new", "comment"};
        commentsConfig.setComment(path, NEWLINE, NEWLINE, "new", "comment");

        // When:
        Map<String, List<String>> updatedComments = commentsConfig.getAllComments();

        // Then:
        assertEquals(Arrays.asList(NEWLINE, NEWLINE), updatedComments.get(path));
    }

    @Test
    public void setComment_throwsNullPointerExceptionForNullPath() {
        // Given:
        CommentsConfiguration commentsConfig = new CommentsConfiguration();
        String[] commentLines = {"new", "comment"};

        // When and Then:
        assertThrows(NullPointerException.class, () -> commentsConfig.setComment(null, NEWLINE, commentLines));
    }

    @Test
    public void setComment_throwsNullPointerExceptionForNullCommentLines() {
        // Given:
        String path = PATH;
        CommentsConfiguration commentsConfig = new CommentsConfiguration();

        // When and Then:
        assertThrows(NullPointerException.class, () -> commentsConfig.setComment(path, null));
    }
}
